examples.code:
fetch('https://api.imagegpt.online/generate/text', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': 'YOUR_API_KEY'
  },
  body: JSON.stringify({
    model: 'GEMINI-2.5-FLASH-LITE',
    system: 'You are a helpful assistant.',
    prompt: 'Explain quantum computing in one paragraph.',
    outputType: 'text',
    maxTokens: 300
  })
})
  .then(res => res.text())
  .then(console.log);

fetch('https://api.imagegpt.online/generate/text-image', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': 'YOUR_API_KEY'
  },
  body: JSON.stringify({
    model: 'FLUX-SCHNELL',
    prompt: 'A futuristic city at sunset, photorealistic',
    width: 512,
    height: 512,
    outputType: 'url',
    outputFormat: 'png'
  })
})
  .then(res => res.json())
  .then(data => console.log('Image URL:', data.url));

