fetch('https://api.imagegpt.online/generate/text-video', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': 'YOUR_API_KEY'
  },
  body: JSON.stringify({
    model: 'KLING-3.0-TURBO',
    prompt: 'A serene sunset over the ocean with gentle waves',
    duration: 6,
    resolution: '720p',
    aspect_ratio: '16:9'
  })
})
  .then(res => res.json())
  .then(data => console.log('Task ID:', data.taskId));

fetch('https://api.imagegpt.online/generate/text-speech', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'x-api-key': 'YOUR_API_KEY'
  },
  body: JSON.stringify({
    prompt: 'Hello, welcome to ImageGPT!',
    model: 'QWEN3/TTS-FLASH',
    outputType: 'binary'
  })
})
  .then(res => res.blob())
  .then(blob => {
    const audio = new Audio(URL.createObjectURL(blob));
    audio.play();
  });
